def test_upload_image(api_client, valid_api_key, pet_id, additional_metadata, file, expected_status):
    """
    Test the /v2/pet/{petId}/uploadImage endpoint with various scenarios.
    """
    headers = {
        "Authorization": f"Bearer {valid_api_key}"
    }
    endpoint = f"v2/pet/{pet_id}/uploadImage" if pet_id else "v2/pet//uploadImage"
    files = {'file': open(file, 'rb')} if file else None
    data = {'additionalMetadata': additional_metadata} if additional_metadata else None

    response = api_client.make_request(endpoint, params=data, headers=headers, method='POST', files=files)
    assert response.status_code == expected_status

    if response.status_code == 200:
        response_json = response.json()
        assert 'code' in response_json
        assert 'type' in response_json
        assert 'message' in response_json

